/**
 * RasdNewsTemplate.tsx
 *
 * Remotion video template for the "عاجل وسط نص" (Breaking News Center Text) layout.
 *
 * ── Config compatibility ──────────────────────────────────────────────────────
 * This template is designed to produce output visually consistent with the
 * static images generated by news_image_lib (Python/Skia). It does so by:
 *
 *  1. Accepting the raw `layout_config.layers` JSON from the template config
 *     and reading all positions, sizes, font paths, and style params from it
 *     (no hardcoded pixel values).
 *
 *  2. Performing the same binary-search font-fit via `useArabicTextFit` hook
 *     (mirrors LayoutEngine._fit_text_to_box).
 *
 *  3. Applying Kashida (tatweel U+0640) justification to non-last lines via
 *     `kashidaJustifyLine` (mirrors ArabicTextHandler.kashida_justify_line).
 *
 *  4. Using the same line-height formula:
 *     - use_metrics_line_spacing=true  → fontBoundingBox × lineSpacing
 *     - use_metrics_line_spacing=false → fontSize × lineSpacing
 *
 * See `arabicUtils.ts` and `hooks/useArabicTextFit.ts` for implementation.
 * See `.agents/skills/arabic-video-text/SKILL.md` for agent guidelines.
 */

import React from "react";
import {
  AbsoluteFill,
  Img,
  OffthreadVideo,
  interpolate,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { loadFont } from "@remotion/fonts";
import { useArabicTextFit } from "./hooks/useArabicTextFit";

// ─── Arabic fonts (Ghroob Arabic) ────────────────────────────────────────────
loadFont({
  family: "GhroobArabic",
  url: staticFile("fonts/GhroobArabicitf-Bold.otf"),
  weight: "700",
  format: "opentype",
});
loadFont({
  family: "GhroobArabic",
  url: staticFile("fonts/GhroobArabicitf-Light.otf"),
  weight: "300",
  format: "opentype",
});

// ─── Types ────────────────────────────────────────────────────────────────────

/** Style block from a news_image_lib text layer config */
export type TextLayerStyle = {
  align?: "left" | "center" | "right";
  color?: string;
  kashida?: boolean;
  direction?: "rtl" | "ltr";
  font_family?: string;
  line_spacing?: number;
  min_font_size?: number;
  base_font_size?: number;
  vertical_align?: "top" | "center" | "bottom";
  use_metrics_line_spacing?: boolean;
  text_background?: {
    enabled?: boolean;
    box_color?: string;
    box_opacity?: number;
    padding_x?: number;
    padding_y?: number;
    corner_radius?: number;
    line_gap?: number;
    text_alignment?: string;
  };
};

/** A text layer from the template JSON layout_config */
export type TextLayerConfig = {
  id: string;
  type: "text";
  x: number;
  y: number;
  width: number;
  max_height: number;
  content?: string; // static default, overridden by dynamic content prop
  style: TextLayerStyle;
  object_key?: string;
  object_type?: string;
};

export type RasdQuoteItem = {
  text: string;
  fadeInStart: number;
  fullyVisibleStart: number;
  fadeOutStart: number;
  hiddenAt: number;
  loopFadeInStart?: number;
};

export type RasdNewsProps = {
  /** Path (staticFile) or URL of the photo/video clip shown in the upper area. */
  photoSrc: string;
  /** Whether the photoSrc is a video (OffthreadVideo) or image (Img). */
  photoIsVideo?: boolean;
  /** Path (staticFile) or URL of the template background image (panel + badge baked in). */
  backgroundImageSrc: string;
  /** The headline quotes to cycle through. */
  quotes: RasdQuoteItem[];
  /** Small label in the bottom-right of the red panel (e.g. source name). */
  sourceText: string;
  /**
   * Raw text layer config from layout_config.layers for the main news headline.
   * When provided, all positioning, sizing, and style params come from this config.
   * When omitted, legacy defaults are used.
   */
  newsTextLayer?: TextLayerConfig;
  /**
   * Raw text layer config from layout_config.layers for the source text.
   */
  sourceTextLayer?: TextLayerConfig;
};

// ─── Legacy defaults (1080 × 1440 canvas) ────────────────────────────────────
// These match the "عاجل وسط نص4" template JSON exactly.

